package e.e.a;
import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.*;
/** Shared neutral surfaces, action icons and compact underline tabs. */
public final class Ui110 {
 public static int actionColor(Context c){return ThemeChoice.isNight(c)?0xff21252d:0xffe5e8eb;}
 public static void circle(View v){v.setBackgroundTintList(null);v.setBackground(PanelUi.round(v.getContext(),actionColor(v.getContext()),100));v.setElevation(0);v.setPadding(0,0,0,0);}
 static void flat(Button b){b.setAllCaps(false);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setBackgroundColor(Color.TRANSPARENT);b.setBackgroundTintList(null);b.setTextColor(PanelUi.ink(b.getContext()));}
 static void primary(Button b){flat(b);b.setBackground(PanelUi.round(b.getContext(),UiDialogs.accent(b.getContext()),12));b.setTextColor(DialogColors.onAccent(UiDialogs.accent(b.getContext())));b.setPadding(PanelUi.dp(b.getContext(),16),0,PanelUi.dp(b.getContext(),16),0);}
 static final class Tabs extends LinearLayout {final TextView[] labels;final View[] bars;final java.util.function.IntConsumer changed;Tabs(Context c,String[] names,java.util.function.IntConsumer callback){super(c);changed=callback;labels=new TextView[names.length];bars=new View[names.length];for(int i=0;i<names.length;i++){final int n=i;LinearLayout slot=PanelUi.column(c);addView(slot,new LayoutParams(0,-2,1));TextView text=PanelUi.text(c,names[i],14);text.setGravity(Gravity.CENTER);text.setMaxLines(1);slot.addView(text,new LayoutParams(-1,PanelUi.dp(c,44)));View bar=new View(c);slot.addView(bar,new LayoutParams(-1,PanelUi.dp(c,2)));labels[i]=text;bars[i]=bar;slot.setOnClickListener(v->changed.accept(n));}select(0);}void select(int at){for(int i=0;i<labels.length;i++){labels[i].setTextColor(i==at?UiDialogs.accent(getContext()):PanelUi.ink(getContext()));bars[i].setBackgroundColor(i==at?UiDialogs.accent(getContext()):Color.TRANSPARENT);}}}
 static final class Swipe extends TabViewport110 {int selected,count;boolean busy;final java.util.function.IntConsumer changed;Swipe(Context c,int count,java.util.function.IntConsumer f){super(c);this.count=count;changed=f;}boolean switching(){return busy;}void swipe(int direction){select(selected+direction);}void select(int next){if(next<0||next>=count||next==selected||busy)return;int dir=next>selected?1:-1;selected=next;View content=getChildAt(0);if(content==null){changed.accept(next);return;}busy=true;content.animate().translationX(-dir*getWidth()).alpha(.4f).setDuration(90).withEndAction(()->{changed.accept(next);content.setTranslationX(dir*getWidth());content.animate().translationX(0).alpha(1).setDuration(150).withEndAction(()->busy=false).start();}).start();}protected void onDetachedFromWindow(){if(getChildCount()>0){getChildAt(0).animate().cancel();getChildAt(0).setTranslationX(0);getChildAt(0).setAlpha(1);}busy=false;super.onDetachedFromWindow();}}
 static TextView compact(Context c,String text,int size){TextView v=PanelUi.text(c,text,size);v.setPadding(0,0,0,0);v.setIncludeFontPadding(false);return v;}
 static Button icon(Context c,String kind){Button b=new Button(c);flat(b);b.setPadding(PanelUi.dp(c,12),PanelUi.dp(c,12),PanelUi.dp(c,12),PanelUi.dp(c,12));b.setCompoundDrawablesWithIntrinsicBounds(new ActionGlyph(c,kind),null,null,null);b.setGravity(Gravity.CENTER);return b;}
 static final class ActionGlyph extends Drawable {final Context c;final String kind;final Paint paint=new Paint(3);ActionGlyph(Context c,String k){this.c=c;kind=k;}public int getIntrinsicWidth(){return PanelUi.dp(c,24);}public int getIntrinsicHeight(){return PanelUi.dp(c,24);}public void draw(Canvas canvas){Rect b=getBounds();canvas.save();canvas.translate(b.left,b.top);canvas.scale(b.width()/24f,b.height()/24f);paint.setColor(PanelUi.ink(c));paint.setStrokeWidth(2);paint.setStrokeCap(Paint.Cap.ROUND);if(kind.equals("back")){paint.setStyle(Paint.Style.STROKE);canvas.drawLine(14,5,7,12,paint);canvas.drawLine(7,12,14,19,paint);}else{paint.setStyle(Paint.Style.FILL);for(int y:new int[]{5,12,19})canvas.drawCircle(12,y,1.7f,paint);}canvas.restore();}public void setAlpha(int a){paint.setAlpha(a);}public void setColorFilter(ColorFilter f){paint.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 public static void like(Button b,boolean liked){flat(b);circle(b);b.setText("");b.setContentDescription(UiStrings.translate("いいね")+(liked?" ✓":""));b.setCompoundDrawables(null,null,null,null);android.graphics.drawable.LayerDrawable background=new android.graphics.drawable.LayerDrawable(new Drawable[]{PanelUi.round(b.getContext(),actionColor(b.getContext()),100),new android.graphics.drawable.InsetDrawable(new Heart(b.getContext(),liked),PanelUi.dp(b.getContext(),9))});b.setBackground(background);b.setCompoundDrawablePadding(0);b.setGravity(Gravity.CENTER);ViewGroup.LayoutParams p=b.getLayoutParams();if(p!=null){p.width=p.height=PanelUi.dp(b.getContext(),40);b.setLayoutParams(p);}}
 static final class Heart extends Drawable {final Paint p=new Paint(3);final Path path=new Path();final Context c;final boolean filled;Heart(Context c,boolean f){this.c=c;filled=f;}public int getIntrinsicWidth(){return PanelUi.dp(c,22);}public int getIntrinsicHeight(){return PanelUi.dp(c,22);}public void draw(Canvas canvas){Rect b=getBounds();canvas.save();canvas.translate(b.left,b.top);canvas.scale(b.width()/24f,b.height()/24f);p.setColor(filled?UiDialogs.accent(c):PanelUi.ink(c));p.setStyle(filled?Paint.Style.FILL:Paint.Style.STROKE);p.setStrokeWidth(1.6f);path.reset();path.moveTo(12,21);path.cubicTo(-5,10,5,-3,12,5);path.cubicTo(19,-3,29,10,12,21);canvas.drawPath(path,p);canvas.restore();}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 static final class Glyph extends View {final String kind;final Paint p=new Paint(3);int color;Glyph(Context c,String k,int color){super(c);kind=k;this.color=color;}protected void onDraw(Canvas c){float scale=Math.min(getWidth(),getHeight())/32f;c.save();c.translate((getWidth()-32*scale)/2,(getHeight()-32*scale)/2);c.scale(scale,scale);p.setColor(color);p.setStrokeWidth(2);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);if(kind.equals("folder")){p.setStyle(Paint.Style.FILL);Path a=new Path();a.moveTo(3,8);a.lineTo(12,8);a.lineTo(16,12);a.lineTo(29,12);a.lineTo(29,27);a.lineTo(3,27);a.close();c.drawPath(a,p);}else if(kind.equals("playlist")){c.drawLine(4,8,22,8,p);c.drawLine(4,14,18,14,p);c.drawLine(4,20,13,20,p);p.setStyle(Paint.Style.FILL);Path a=new Path();a.moveTo(19,17);a.lineTo(28,23);a.lineTo(19,29);a.close();c.drawPath(a,p);}else{c.drawRoundRect(6,3,24,27,2,2,p);c.drawLine(10,10,19,10,p);c.drawLine(10,15,17,15,p);p.setColor(UiDialogs.surface(getContext()));p.setStyle(Paint.Style.FILL);c.drawCircle(24,24,7,p);p.setColor(color);p.setStyle(Paint.Style.STROKE);c.drawCircle(24,24,6,p);c.drawLine(20,20,28,28,p);}c.restore();}}
}
